import { Effect, Schema } from "effect"
import { HttpApiSSE } from "@effect/platform"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.Number }) {}
const U = Schema.Union(A, B)

// transformed union
const Transformed = Schema.transform(U, U, { decode: (x) => x, encode: (x) => x })
// suspended union
const Suspended = Schema.suspend(() => U)
// union with suspended member
const Wrapped = Schema.Union(A, Schema.suspend(() => B))
// single TaggedClass (non-union)
const Single = A

const cases: Array<[string, Schema.Schema<any>]> = [
  ["union", U],
  ["transformed", Transformed],
  ["suspended", Suspended],
  ["wrapped", Wrapped],
  ["single", Single]
]

Effect.runPromise(Effect.gen(function*() {
  for (const [name, schema] of cases) {
    const enc = HttpApiSSE.makeUnionEventEncoder(schema)
    const dec = HttpApiSSE.makeUnionEventDecoder(schema)
    const msg = yield* enc(new A({ a: "x" }) as any)
